import * as sys from "node:sys";
import * as util from "node:util";
function main(): void {
  const s: any = sys;
  console.log("inherits:" + sys.inherits.length + "/" + util.inherits.length + " " + "format:" + sys.format.length + "/" + util.format.length + " " + "formatWithOptions:" + sys.formatWithOptions.length + "/" + util.formatWithOptions.length + " " + "deprecate:" + sys.deprecate.length + "/" + util.deprecate.length + " " + "isBoolean:" + sys.isBoolean.length + "/" + util.isBoolean.length + " " + "isError:" + sys.isError.length + "/" + util.isError.length + " " + "toUSVString:" + sys.toUSVString.length + "/" + util.toUSVString.length + " " + "parseEnv:" + sys.parseEnv.length + "/" + util.parseEnv.length + " " + "debug:" + sys.debug.length + "/" + util.debug.length + " " + "diff:" + sys.diff.length + "/" + util.diff.length + " " + "getSystemErrorMessage:" + sys.getSystemErrorMessage.length + "/" + util.getSystemErrorMessage.length + " " + "_extend:" + sys._extend.length + "/" + util._extend.length + " " + "isBuffer:" + sys.isBuffer.length + "/" + util.isBuffer.length + " " + "setTraceSigInt:" + sys.setTraceSigInt.length + "/" + util.setTraceSigInt.length);
  console.log(s.isBoolean(true), s.isError(new Error("x")), s._extend({ a: 1 }, { b: 2 }).b, s.getSystemErrorMessage(-2), JSON.stringify(s.parseEnv("A=1\nB=\"x y\" # c")), JSON.stringify(s.diff("abc", "abd")), s.getSystemErrorMap().size > 50);
  console.log(Object.keys(new s.TextDecoder()).length, Object.keys(new s.MIMEParams()).length, String(new s.MIMEType("text/plain;a=b")));
}
